fn test_whitespace_only() {
    // Whitespace-only content
    let html = r#"<p>   </p>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert_eq!(_content.to_string(), r#""#, "equals assertion failed");
}

#[test]
fn test_xss_onclick_handler_removed() {
    // onclick and other on* event handlers are removed from elements
    let html = r#"<p><a href="https://example.com" onclick="alert('xss')">Click me</a></p><button onmouseover="steal_data()">Hover me</button>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(
        _content.contains(r#"Click me"#),
        "expected to contain: {}",
        r#"Click me"#
    );
    assert!(
        !_content.contains(r#"onclick"#),
        "expected NOT to contain: {}",
        r#"onclick"#
    );
    assert!(
        !_content.contains(r#"onmouseover"#),
        "expected NOT to contain: {}",
        r#"onmouseover"#
    );
    assert!(
        !_content.contains(r#"alert("#),
        "expected NOT to contain: {}",
        r#"alert("#
    );
    assert!(
        !_content.contains(r#"steal_data"#),
        "expected NOT to contain: {}",
        r#"steal_data"#
    );
}

#[test]
fn test_xss_script_tag_stripped() {
    // Script tag content is stripped and does not appear in output
    let html = r#"<p>Safe content.</p><script>alert('xss')</script><p>More safe content.</p>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(
        _content.contains(r#"Safe content"#),
        "expected to contain: {}",
        r#"Safe content"#
    );
    assert!(
        _content.contains(r#"More safe content"#),
        "expected to contain: {}",
        r#"More safe content"#
    );
    assert!(
        !_content.contains(r#"<script>"#),
        "expected NOT to contain: {}",
        r#"<script>"#
    );
    assert!(
        !_content.contains(r#"alert("#),
        "expected NOT to contain: {}",
        r#"alert("#
    );
    assert!(!_content.contains(r#"xss"#), "expected NOT to contain: {}", r#"xss"#);
}

#[test]
fn test_xss_svg_nested_script_stripped() {
    // Script tags nested inside SVG are stripped
    let html = r#"<p>Before SVG.</p><svg xmlns="http://www.w3.org/2000/svg"><script>alert('svg-xss')</script><text>SVG text</text></svg><p>After SVG.</p>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(
        _content.contains(r#"Before SVG"#),
        "expected to contain: {}",
        r#"Before SVG"#
    );
    assert!(
        _content.contains(r#"After SVG"#),
        "expected to contain: {}",
        r#"After SVG"#
    );
    assert!(
        !_content.contains(r#"<script>"#),
        "expected NOT to contain: {}",
        r#"<script>"#
    );
    assert!(
        !_content.contains(r#"alert("#),
        "expected NOT to contain: {}",
        r#"alert("#
    );
    assert!(
        !_content.contains(r#"svg-xss"#),
        "expected NOT to contain: {}",
        r#"svg-xss"#
    );
}
